const clean = (value, limit = 200) => typeof value === 'string' ? value.trim().slice(0, limit) : '';
const sessionId = clean($json.session_id, 100);
const requestId = clean($json.request_id, 100) || 'prospects-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8);
const splitTerms = (value, maximum) => [...new Set(clean(value, 300).split(/[,;|]/).map((term) => term.trim()).filter(Boolean))].slice(0, maximum);
const jobTitles = splitTerms($json.job_titles, 5);
const sector = clean($json.sector, 120);
const location = clean($json.location, 120);
const companySize = clean($json.company_size, 20);
const allowedSizes = new Set(['', '1-10', '11-50', '51-200', '201-500', '501-1000', '1001+']);
const requestedLimit = Number($json.result_limit ?? 5);
const resultLimit = Number.isInteger(requestedLimit) ? Math.max(1, Math.min(10, requestedLimit)) : 5;
const paidSearchConfirmed = $json.paid_search_confirmed === true;
let errorCode = '';
let errorMessage = '';
if (jobTitles.length === 0 && !sector) {
  errorCode = 'SEARCH_CRITERIA_REQUIRED';
  errorMessage = 'Provide at least one current job title or a sector before searching.';
} else if (!allowedSizes.has(companySize)) {
  errorCode = 'INVALID_COMPANY_SIZE';
  errorMessage = 'Company size must be 1-10, 11-50, 51-200, 201-500, 501-1000, 1001+, or blank.';
} else if (!paidSearchConfirmed) {
  errorCode = 'PAID_SEARCH_APPROVAL_REQUIRED';
  errorMessage = 'Before searching, explicitly approve one Crustdata prospect search costing up to 0.30 credits.';
}
const conditions = [];
if (jobTitles.length === 1) {
  conditions.push({ field: 'experience.employment_details.current.title', type: '(.)', value: jobTitles[0] });
} else if (jobTitles.length > 1) {
  conditions.push({ op: 'or', conditions: jobTitles.map((title) => ({ field: 'experience.employment_details.current.title', type: '(.)', value: title })) });
}
if (sector) conditions.push({ field: 'experience.employment_details.current.company_industries', type: '(.)', value: sector });
if (location) conditions.push({ field: 'basic_profile.location.full_location', type: '(.)', value: location });
const filters = conditions.length === 1 ? conditions[0] : { op: 'and', conditions };
const searchBody = {
  filters,
  fields: ['metadata.updated_at', 'basic_profile', 'experience.employment_details.current', 'social_handles.professional_network_identifier.profile_url'],
  limit: resultLimit
};
return { json: {
  valid: errorCode === '', errorCode, errorMessage, sessionId, requestId,
  jobTitles, sector, location, companySize, resultLimit, paidSearchConfirmed,
  searchBody, maxCredits: 0.30
} };

const input = $('Validate Prospect Input').first().json;
const statusCode = Number($json.statusCode ?? 200);
const body = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const headers = $json.headers && typeof $json.headers === 'object' ? $json.headers : {};
const creditsUsed = Number(headers['x-credits-used'] ?? headers['X-Credits-Used'] ?? 0) || 0;
const criteria = { job_titles: input.jobTitles, sector: input.sector, location: input.location, company_size: input.companySize, result_limit: input.resultLimit };
if (statusCode < 200 || statusCode >= 300) {
  return { json: { response: { ok: false, search_status: 'unavailable', criteria, prospects: [], credits_used: creditsUsed, message: 'The professional-data provider was unavailable (HTTP ' + statusCode + '). No automatic retry was made.' } } };
}
const normalise = (value) => String(value ?? '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const linkedinSlug = (value) => {
  const url = String(value ?? '').trim();
  try {
    const parsed = new URL(url);
    const host = parsed.hostname.toLowerCase();
    if ((host !== 'linkedin.com' && !host.endsWith('.linkedin.com')) || !parsed.pathname.startsWith('/in/')) return '';
    const slug = parsed.pathname.slice(4).split('/')[0];
    return /^[a-z0-9%_.-]+$/i.test(slug) ? slug : '';
  } catch { return ''; }
};
const sizeRange = (label) => {
  if (!label) return null;
  if (label === '1001+') return [1001, Number.POSITIVE_INFINITY];
  const parts = label.split('-').map(Number);
  return parts.length === 2 && parts.every(Number.isFinite) ? parts : null;
};
const requestedRange = sizeRange(input.companySize);
const wantedTitles = (input.jobTitles ?? []).map(normalise).filter(Boolean);
const wantedSector = normalise(input.sector);
const wantedLocation = normalise(input.location);
const profiles = Array.isArray(body.profiles) ? body.profiles : [];
const rows = profiles.map((raw) => {
  const basic = raw.basic_profile && typeof raw.basic_profile === 'object' ? raw.basic_profile : {};
  const location = basic.location && typeof basic.location === 'object' ? basic.location : {};
  const current = raw.experience?.employment_details?.current;
  const jobs = Array.isArray(current) ? current : [];
  const primary = jobs.find((job) => job?.is_default === true) ?? jobs[0] ?? {};
  const url = String(raw.social_handles?.professional_network_identifier?.profile_url ?? '').trim();
  const slug = linkedinSlug(url);
  if (!slug) return null;
  const name = String(basic.professional_network_name ?? basic.name ?? '').trim();
  const title = String(basic.current_title ?? primary.title ?? '').trim();
  const company = String(primary.name ?? primary.company_name ?? '').trim();
  const industries = [...new Set(jobs.flatMap((job) => [
    ...(Array.isArray(job?.company_industries) ? job.company_industries : []),
    job?.company_professional_network_industry
  ]).map((value) => String(value ?? '').trim()).filter(Boolean))];
  const displayLocation = String(location.full_location ?? location.raw ?? [location.city, location.state, location.country].filter(Boolean).join(', ')).trim();
  const headcountCandidates = [primary.company_headcount, primary.company_employee_count, primary.employee_count, primary.company_size];
  const headcount = headcountCandidates.map(Number).find((value) => Number.isFinite(value) && value >= 0) ?? null;
  const professionalText = normalise([title, industries.join(' '), company, basic.headline, ...jobs.flatMap((job) => [job?.title, job?.function_category, job?.description])].join(' '));
  let score = 0;
  const evidence = [];
  if (wantedTitles.some((wanted) => normalise(title).includes(wanted) || professionalText.includes(wanted))) { score += 45; evidence.push('current role'); }
  if (wantedSector && professionalText.includes(wantedSector)) { score += 30; evidence.push('sector'); }
  if (wantedLocation && normalise(displayLocation).includes(wantedLocation)) { score += 15; evidence.push('location'); }
  if (requestedRange && headcount !== null && headcount >= requestedRange[0] && headcount <= requestedRange[1]) { score += 10; evidence.push('company size'); }
  return {
    score: Math.min(100, score),
    prospect: {
      name: name || null,
      linkedin_url: url,
      public_identifier: slug,
      current_title: title || null,
      current_company: company || null,
      location: displayLocation || null,
      industry: industries.join(', ') || null,
      company_headcount: headcount,
      evidence
    }
  };
}).filter(Boolean).sort((left, right) => right.score - left.score);
const prospects = rows.slice(0, input.resultLimit).map((row) => row.prospect);
const warnings = [];
if (input.companySize && prospects.some((prospect) => prospect.company_headcount === null)) warnings.push('Company headcount was not returned for every prospect, so the size band could not be confirmed for those rows.');
if (prospects.length === 0) warnings.push('No public professional profile matched the approved criteria. Broaden or correct the brief before approving another paid search.');
return { json: { response: {
  ok: true,
  search_status: prospects.length > 0 ? 'complete' : 'not_found',
  criteria,
  prospects,
  warnings,
  credits_used: creditsUsed,
  total_matches: Number(body.total_count ?? prospects.length),
  returned_matches: profiles.length,
  message: prospects.length > 0 ? 'Possible prospects were returned from the approved public professional-data search. Verify fit before using the list.' : warnings[0]
} } };

const input = $('Validate Prospect Input').first().json;
const response = $json.response;
const error = response?.ok === false ? String(response.error?.message ?? response.message ?? 'Tool failed') : '';
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'search_linkedin_prospects', proposedInput: JSON.stringify({ job_titles: input.jobTitles, sector: input.sector, location: input.location, company_size: input.companySize, result_limit: input.resultLimit, maximum_credits: input.maxCredits }), result: error ? 'error' : String(response.search_status ?? 'ok'), error, response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The lookup result could not be written to the local tool audit.';
return { json: response };
